package com.rulecraft.decisionops.versions.api;
import com.rulecraft.decisionops.identity.security.CurrentUser;import com.rulecraft.decisionops.versions.DecisionVersionService;import com.rulecraft.decisionops.versions.DecisionVersionService.*;import java.util.*;import org.springframework.http.HttpStatus;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/projects/{projectId}/decision-services/{serviceId}/versions")
public class DecisionVersionController {private final DecisionVersionService service;public DecisionVersionController(DecisionVersionService service){this.service=service;}@GetMapping List<VersionSummary> list(@PathVariable UUID projectId,@PathVariable UUID serviceId,Authentication authentication){return service.list(CurrentUser.require(authentication),projectId,serviceId);}@GetMapping("/working")WorkingState working(@PathVariable UUID projectId,@PathVariable UUID serviceId,Authentication authentication){return service.working(CurrentUser.require(authentication),projectId,serviceId);}@PostMapping @ResponseStatus(HttpStatus.CREATED)VersionSummary capture(@PathVariable UUID projectId,@PathVariable UUID serviceId,@RequestBody CaptureCommand body,Authentication authentication){return service.capture(CurrentUser.require(authentication),projectId,serviceId,body);}@GetMapping("/diff")VersionDiff diff(@PathVariable UUID projectId,@PathVariable UUID serviceId,@RequestParam UUID baseId,@RequestParam UUID targetId,Authentication authentication){return service.diff(CurrentUser.require(authentication),projectId,serviceId,baseId,targetId);}}
